"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["9471"],{9589(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>h,frontMatter:()=>o,contentTitle:()=>r,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"SoftwareEngineering/database-design","title":"Database Design Principles","description":"How data is structured has a lasting impact on an application\'s correctness and performance \u2014 schema mistakes are often the hardest kind of technical debt to fix later, because they require a live data migration, not just a code change.","source":"@site/docs/SoftwareEngineering/14-database-design.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/database-design","permalink":"/Mindstack/docs/SoftwareEngineering/database-design","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":14,"frontMatter":{"title":"Database Design Principles","sidebar_label":"Database Design","sidebar_position":14},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Architectural Patterns","permalink":"/Mindstack/docs/SoftwareEngineering/architectural-patterns"},"next":{"title":"Caching Strategies","permalink":"/Mindstack/docs/SoftwareEngineering/caching-strategies"}}'),i=t(4848),s=t(8453);let o={title:"Database Design Principles",sidebar_label:"Database Design",sidebar_position:14},r="Database Design Principles",l={},c=[{value:"Normalization",id:"normalization",level:2},{value:"When to Denormalize",id:"when-to-denormalize",level:2},{value:"Choosing SQL vs NoSQL",id:"choosing-sql-vs-nosql",level:2},{value:"Indexing",id:"indexing",level:2},{value:"Transactions and ACID",id:"transactions-and-acid",level:2},{value:"Migrations",id:"migrations",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"database-design-principles",children:"Database Design Principles"})}),"\n",(0,i.jsx)(n.p,{children:"How data is structured has a lasting impact on an application's correctness and performance \u2014 schema mistakes are often the hardest kind of technical debt to fix later, because they require a live data migration, not just a code change."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"normalization",children:"Normalization"}),"\n",(0,i.jsx)(n.p,{children:"Organizing relational data to minimize redundancy and avoid update anomalies \u2014 the same fact should live in exactly one place."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'UNNORMALIZED \u2014 customer info repeated on every order row\n\norders table:\n  order_id | customer_name  | customer_email       | item\n  1        | Alice Smith    | alice@example.com    | Widget\n  2        | Alice Smith    | alice@example.com    | Gadget\n  3        | Bob Jones      | bob@example.com      | Widget\n\nProblem: if Alice updates her email, EVERY row mentioning her needs\nupdating \u2014 miss one, and you now have inconsistent data with no way\nto tell which value is "correct."\n\n\nNORMALIZED \u2014 customer info lives in exactly one place\n\ncustomers table:\n  customer_id | name          | email\n  1           | Alice Smith   | alice@example.com\n  2           | Bob Jones     | bob@example.com\n\norders table:\n  order_id | customer_id | item\n  1        | 1            | Widget\n  2        | 1            | Gadget\n  3        | 2            | Widget\n\nAlice\'s email now lives in exactly one row. Updating it once updates\nthe single source of truth; every order referencing customer_id=1\nreflects the change automatically via the relationship, with no risk\nof inconsistency.\n'})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"The normal forms, briefly (most real schemas aim for 3NF in practice):\n\n1NF \u2014 each column holds a single, atomic value (no comma-separated\n      lists crammed into one field)\n2NF \u2014 every non-key column depends on the WHOLE primary key (matters\n      most for composite keys)\n3NF \u2014 every non-key column depends ONLY on the key, not on another\n      non-key column (the customer_name/email example above \u2014 they\n      depended on customer_id, not on order_id, so they didn't belong\n      in the orders table at all)\n\nIn practice: most engineers don't consciously reason through 1NF/2NF/\n3NF definitions on every table \u2014 the practical habit that gets you\nthere is simply \"does this fact belong to THIS entity, or does it\nactually belong to a related entity I should reference instead?\"\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"when-to-denormalize",children:"When to Denormalize"}),"\n",(0,i.jsx)(n.p,{children:"Normalization optimizes for data integrity and update simplicity \u2014 but it requires JOINs to reassemble related data, which cost real query performance at scale. Denormalization deliberately reintroduces some redundancy to trade write-time complexity for read-time speed."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Normalized (requires a JOIN on every read):\n\n  SELECT orders.id, orders.item, customers.name\n  FROM orders\n  JOIN customers ON orders.customer_id = customers.id\n  WHERE orders.id = 123\n\nDenormalized (customer_name copied directly onto the order,\nusually at write/order-creation time):\n\n  orders table:\n    order_id | customer_id  | customer_name  | item\n    123      | 1            | Alice Smith    | Widget\n\n  SELECT id, item, customer_name FROM orders WHERE id = 123\n  -- no JOIN needed; faster, especially at high read volume\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Denormalize when:\n  A specific query is measurably slow due to expensive JOINs, and\n  you've confirmed this with real profiling (not a guess)\n  Read volume vastly exceeds write volume for this data (an order's\n  customer_name rarely changes after the order is placed \u2014 copying\n  it at order time captures a meaningful historical fact: \"who this\n  order actually belonged to AT THE TIME,\" which is often what you\n  actually want for orders anyway, since a later name change\n  shouldn't rewrite history)\n  You're building a dedicated read model (see CQRS, file 12) specifically\n  optimized for a known, common query pattern\n\nStay normalized when:\n  You haven't yet demonstrated a real performance problem (premature\n  denormalization is premature optimization \u2014 see file 24, Anti-Patterns)\n  The data changes frequently and consistency matters more than raw\n  read speed for that specific case\n\nThis is the same YAGNI/KISS judgment call (file 04) applied to schema\ndesign \u2014 don't denormalize speculatively; do it in response to a\ndemonstrated, measured need.\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"choosing-sql-vs-nosql",children:"Choosing SQL vs NoSQL"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"                        SQL (Relational)            NoSQL (varies by type)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nSchema                  Fixed, enforced             Flexible/schemaless\n                        upfront                     (or schema-on-read)\nRelationships           Native (JOINs,              Often denormalized;\n                        foreign keys)               relationships\n                                                    modeled in application\n                                                    code or embedded\nConsistency             Strong (ACID                Often eventual\n                        transactions)               consistency by default\n                                                    (see file 17)\nScaling                 Vertical primarily,         Horizontal scaling\n                        horizontal read             often a first-class\n                        replicas common,            design goal\n                        horizontal WRITE\n                        scaling (sharding)\n                        is harder\nBest fit                Data with genuine           Very high write\n                        relationships,              throughput, flexible/\n                        strong consistency          evolving schemas,\n                        needs (financial            massive horizontal\n                        transactions,               scale needs, simple\n                        inventory counts)           key-value or document\n                                                    access patterns\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"NoSQL is not one thing \u2014 it's several genuinely different models,\neach suited to different problems:\n\nDocument stores (MongoDB, Couchbase):\n  JSON-like documents, flexible schema, good fit when your data\n  naturally nests (a blog post with embedded comments) and you\n  usually fetch the whole document together\n\nKey-value stores (Redis, DynamoDB in simple mode):\n  Extremely fast, simple lookups by key \u2014 session storage, caching,\n  feature flags, anything accessed by a known ID with no complex querying\n\nWide-column stores (Cassandra, HBase):\n  Designed for massive write throughput and horizontal scale across\n  many machines \u2014 time-series data, event logging, IoT sensor data\n\nGraph databases (Neo4j):\n  Optimized specifically for traversing RELATIONSHIPS \u2014 social\n  networks, recommendation engines, fraud detection networks where\n  the connections between data ARE the primary thing you're querying\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'A practical decision test:\n\n  "Does this data have clear entities with meaningful RELATIONSHIPS\n  between them, and do I need strong consistency guarantees?"\n    \u2192 SQL is very likely the right default\n\n  "Is this data naturally document-shaped, or do I need extreme\n  write throughput / horizontal scale beyond what a single SQL\n  database (even with read replicas) can handle?"\n    \u2192 A specific NoSQL model, chosen for the SPECIFIC access pattern,\n      not "NoSQL in general"\n\nMany real systems use BOTH \u2014 SQL for the core transactional data\n(orders, users, payments) and a specific NoSQL store for a specific\nneed (Redis for caching/sessions, Elasticsearch for full-text search) \u2014\npolyglot persistence, choosing the right tool per access pattern\nrather than forcing one database technology to serve every need.\n'})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"indexing",children:"Indexing"}),"\n",(0,i.jsx)(n.p,{children:"An index lets the database find rows without scanning the entire table \u2014 the single highest-leverage performance tool in most relational databases, and one of the most commonly under-used."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-sql",children:"-- Without an index, this query scans EVERY row in the table\nSELECT * FROM orders WHERE customer_id = 42;\n\n-- An index on customer_id lets the database jump directly to\n-- matching rows instead of scanning the whole table\nCREATE INDEX idx_orders_customer_id ON orders(customer_id);\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Index the columns you actually:\n  Filter by (WHERE clauses)\n  Join on (foreign key columns used in JOIN conditions)\n  Sort by (ORDER BY, if done frequently on the same column)\n\nComposite indexes (covering multiple columns) help when you\nfrequently filter on the SAME combination of columns together:\n  CREATE INDEX idx_orders_customer_status\n    ON orders(customer_id, status);\n  -- helps: WHERE customer_id = 42 AND status = 'pending'\n  -- helps (leftmost prefix): WHERE customer_id = 42\n  -- does NOT help: WHERE status = 'pending'  (alone, without customer_id)\n\nThe cost of indexes: every index speeds up READS but slows down\nWRITES (the index itself must be updated on every insert/update/\ndelete) and consumes additional storage. Index the columns your\nactual query patterns need \u2014 indexing every column \"just in case\"\ntrades write performance for a benefit most of those indexes will\nnever actually provide.\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"transactions-and-acid",children:"Transactions and ACID"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Atomicity   \u2014 a transaction either fully completes or fully rolls\n              back; no partial changes are ever left visible\nConsistency  \u2014 a transaction takes the database from one valid state\n              to another, never violating defined constraints\nIsolation     \u2014 concurrent transactions don't interfere with each\n              other's intermediate states\nDurability     \u2014 once committed, a transaction's changes survive even\n              a subsequent crash\n\nExample: transferring money between two accounts MUST be atomic \u2014\ndebiting one account and crediting the other must both succeed, or\nboth roll back. A crash between the two steps must never leave money\ndebited from one account without being credited to the other.\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:"# Wrapping a multi-step operation in a transaction \u2014 see the Echo\n# course's database page for the GORM-specific version of this pattern\ndef transfer_money(from_account, to_account, amount):\n    with db.transaction():\n        debit(from_account, amount)\n        credit(to_account, amount)\n        # if EITHER step raises an exception, the transaction rolls\n        # back entirely \u2014 the database is never left in a half-done state\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"migrations",children:"Migrations"}),"\n",(0,i.jsx)(n.p,{children:"Schema changes need to be applied consistently and safely across every environment (local dev, staging, production) \u2014 hand-editing a production schema is a serious operational risk."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Migration tools (Flyway, Alembic, golang-migrate, Django migrations,\nRails ActiveRecord migrations) let you:\n  Define schema changes as versioned, ordered files\n  Apply them consistently, in order, to any environment\n  Track which migrations have already run, so re-running is safe\n  Roll back a specific change if something goes wrong\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-sql",children:"-- migrations/0004_add_orders_status_index.sql\nCREATE INDEX idx_orders_status ON orders(status);\n\n-- migrations/0004_add_orders_status_index_rollback.sql\nDROP INDEX idx_orders_status;\n"})}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Safe migration practices for production systems with real traffic:\n  Additive changes first (add a new column as NULLABLE, deploy code\n  that writes to it, THEN make it required in a later migration) \u2014\n  avoids a window where old code and new schema are incompatible\n  Avoid long-running locks on large tables during business hours \u2014\n  some schema changes (adding an index on a huge table) can lock\n  writes for an extended period; many databases offer online/\n  concurrent index creation specifically to avoid this\n  Always have a tested rollback path before running a migration\n  against production\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Normalize by default; denormalize only in response to a measured, real performance problem \u2014 premature denormalization is premature optimization applied to schema design."}),"\n",(0,i.jsx)(n.li,{children:"Index the columns your actual queries filter, join, and sort on \u2014 not every column speculatively; every index has a real write-performance and storage cost."}),"\n",(0,i.jsx)(n.li,{children:"Choose SQL vs NoSQL (and which flavor of NoSQL) based on the actual access pattern and consistency needs of that specific data \u2014 most real systems use more than one database technology, each for what it's genuinely best at."}),"\n",(0,i.jsx)(n.li,{children:"Wrap any multi-step operation that must succeed or fail as a unit in a database transaction \u2014 never leave room for a crash to result in a half-completed, inconsistent state."}),"\n",(0,i.jsx)(n.li,{children:'Use a migration tool from day one, even on a small project \u2014 hand-editing schemas across environments is a reliable source of "works on my machine, breaks in production" incidents.'}),"\n"]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:'Normalization eliminates redundancy by ensuring each fact lives in one place \u2014 the practical test is "does this column depend on THIS table\'s key, or on a related entity?"'}),"\n",(0,i.jsx)(n.li,{children:"Denormalization trades write-time complexity for read-time speed \u2014 apply it in response to a measured performance need, not speculatively."}),"\n",(0,i.jsx)(n.li,{children:"SQL fits data with genuine relationships and strong consistency needs; NoSQL is several distinct models (document, key-value, wide-column, graph), each suited to a specific access pattern \u2014 many real systems combine both."}),"\n",(0,i.jsx)(n.li,{children:"Indexes are the highest-leverage performance tool for reads, at a real cost to writes and storage \u2014 index based on actual query patterns."}),"\n",(0,i.jsx)(n.li,{children:"ACID transactions guarantee multi-step operations complete fully or not at all, even across a crash \u2014 wrap any operation requiring this guarantee explicitly."}),"\n",(0,i.jsx)(n.li,{children:"Use a migration tool to apply schema changes consistently and safely across environments, with additive-first changes and tested rollback paths for production systems."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>r});var a=t(6540);let i={},s=a.createContext(i);function o(e){let n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),a.createElement(s.Provider,{value:n},e.children)}}}]);